var root = java.nio.file.Files.createTempDirectory("codeklar-");
var a = root.resolve("a.txt"); var b = root.resolve("b.txt");
try {
    java.nio.file.Files.writeString(a, "Ada");
    java.nio.file.Files.copy(a, b);
    System.out.println(java.nio.file.Files.readString(b));
    System.out.println(java.nio.file.Files.exists(a));
} finally { java.nio.file.Files.deleteIfExists(b); java.nio.file.Files.deleteIfExists(a); java.nio.file.Files.deleteIfExists(root); }

